starterCode:
async function fetchWithTimeout(url, timeoutMs) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetch(url, { signal: controller.signal });
    clearTimeout(timer);
    return await res.json();
  } catch (err) {
    clearTimeout(timer);
    throw err;
  }
}

testHarness:
await $test.rejects("Request slower than timeoutMs is aborted", async () => {
  const sleep = $test.sleep;
  return (fetchWithTimeout('https://jsonplaceholder.typicode.com/photos', 1));
}, "abort");

await $test.run("Fast request resolves with its JSON and the timer is cleared", async () => {
  const sleep = $test.sleep;
  return (fetchWithTimeout('https://jsonplaceholder.typicode.com/todos/1', 5000));
}, () => ({ userId: 1, id: 1, title: 'delectus aut autem', completed: false }));

await $test.run("clearTimeout is called after a successful response", async () => {
  const sleep = $test.sleep;
  const realClear = globalThis.clearTimeout;
  let cleared = 0;
  globalThis.clearTimeout = (id) => { cleared++; return realClear(id); };
  try { await fetchWithTimeout('https://jsonplaceholder.typicode.com/todos/1', 5000); } finally { globalThis.clearTimeout = realClear; }
  return (cleared >= 1);
}, () => (true));

